import {NextResponse} from 'next/server';import {prisma} from '../../../../lib/prisma';import {requireApiUser} from '../../../../lib/apiAuth';import {redirectTo} from '../../../../lib/http';
export async function POST(req,{params}){const a=await requireApiUser(['Admin']);if(a.error)return NextResponse.json({error:a.error},{status:a.status});const id=Number(params.id),f=await req.formData(),name=String(f.get('name')||'').trim(),contactInfo=String(f.get('contactInfo')||'').trim()||null,lead=String(f.get('leadTimeDays')||'').trim();await prisma.vendor.update({where:{id},data:{name,contactInfo,leadTimeDays:lead?Number(lead):null}});return redirectTo(`/vendors/${id}`)}
